const state = $input.first().json;
const items = state.data.kamienie_milowe;

const listaTekst = items.map(m => '- id: ' + m.id + ' | ' + m.nazwa + ' | obecny znany status: ' + m.status + ' | obecna znana data: ' + m.data_aktualna).join('\n');

const systemPrompt = 'Jestes asystentem monitorujacym europejskie przepisy o sztucznej inteligencji (rozporzadzenie UE 2024/1689 wraz z nowelizacjami, m.in. Digital Omnibus 2026/1744). Sprawdzasz wylacznie fakty ze znalezionych zrodel, niczego nie zgadujesz. Zwracasz WYLACZNIE dane zgodne z podanym schematem JSON, bez zadnego dodatkowego tekstu ani komentarza.';

const userPrompt = 'Sprawdz, czy pojawily sie wiarygodne informacje o zmianie statusu lub daty ponizszych kamieni milowych AI Act:\n\n' + listaTekst + '\n\nStatus "potwierdzona_zmiana" mozesz nadac WYLACZNIE jesli informacja pochodzi z eur-lex.europa.eu lub digital-strategy.ec.europa.eu. Informacje z innych dozwolonych zrodel moga dac co najwyzej "zapowiedziana_zmiana". Brak nowych informacji = "bez_zmian".';

const body = {
  model: 'sonar',
  max_tokens: 4096,
  messages: [
    { role: 'system', content: systemPrompt },
    { role: 'user', content: userPrompt }
  ],
  response_format: {
    type: 'json_schema',
    json_schema: {
      name: 'milestones_check',
      schema: {
        type: 'object',
        properties: {
          items: {
            type: 'array',
            items: {
              type: 'object',
              properties: {
                id: { type: 'string' },
                ocena: { type: 'string', enum: ['bez_zmian', 'zapowiedziana_zmiana', 'potwierdzona_zmiana'] },
                nowa_data: { type: ['string', 'null'] },
                zrodlo_domena: { type: 'string' },
                notatka: { type: 'string' }
              },
              required: ['id', 'ocena', 'zrodlo_domena', 'notatka']
            }
          }
        },
        required: ['items']
      }
    }
  },
  search_domain_filter: ['eur-lex.europa.eu', 'digital-strategy.ec.europa.eu', 'artificialintelligenceact.eu', 'iapp.org', 'euractiv.com', 'lexology.com'],
  search_recency_filter: 'month'
};

return [{ json: { requestBody: body } }];

const text = $json.choices[0].message.content;
const parsed = JSON.parse(text);
return [{ json: parsed }];

const previous = $('Parse State').first().json.data.kamienie_milowe || [];
const ocenyBy = {};
for (const o of $json.items) {
  ocenyBy[o.id] = o;
}

const oficjalne = ['eur-lex.europa.eu', 'digital-strategy.ec.europa.eu'];

const zaktualizowane = previous.map(item => {
  const ocena = ocenyBy[item.id];
  if (!ocena || ocena.ocena === 'bez_zmian') {
    return { ...item, zmieniono_w_tym_uruchomieniu: false };
  }
  const zrodloOficjalne = oficjalne.some(d => (ocena.zrodlo_domena || '').includes(d));
  if (ocena.ocena === 'potwierdzona_zmiana' && zrodloOficjalne) {
    return {
      ...item,
      status: 'przesuniete',
      data_aktualna: ocena.nowa_data || item.data_aktualna,
      ostatnia_zmiana: ocena.notatka,
      zmieniono_w_tym_uruchomieniu: true
    };
  }
  if (item.status !== 'przesuniete') {
    // sygnal branzowy: oznaczamy jako zmiane tylko jesli faktycznie cos nowego,
    // inaczej ta sama plotka wracalaby w sekcji "co sie zmienilo" co tydzien
    const nowosc = item.status !== 'zagrozony_zmiana' || item.ostatnia_zmiana !== ocena.notatka;
    return {
      ...item,
      status: 'zagrozony_zmiana',
      ostatnia_zmiana: ocena.notatka,
      zmieniono_w_tym_uruchomieniu: nowosc
    };
  }
  return { ...item, zmieniono_w_tym_uruchomieniu: false };
});

return [{ json: { kamienie_milowe: zaktualizowane } }];

const systemPrompt = 'Jestes precyzyjnym asystentem monitorujacym WYLACZNIE formalnie wydane akty prawne i oficjalne dokumenty wykonawcze do unijnego AI Act (rozporzadzenie 2024/1689): akty delegowane, akty wykonawcze (implementing regulations), oficjalne wytyczne (guidelines) Komisji Europejskiej lub AI Office publikowane jako formalna Komunikacja, oraz uznane Kodeksy Postepowania (np. GPAI Code of Practice). NIE zaliczaj do tej kategorii: artykulow informacyjnych, wpisow spolecznosciowych z platformy Futurium, poradnikow ani playbookow tworzonych przez spolecznosc, oswiadczen o prywatnosci/RODO, stron z czestymi pytaniami, narzedzi typu Explorer, komunikatow prasowych bez konkretnego aktu, ani niczego, co nie jest nazwanym, konkretnym aktem prawnym z tytulem lub numerem referencyjnym. Jesli po przeszukaniu zrodel nie znajdziesz ZADNEGO wpisu spelniajacego te kryteria, zwroc akty jako pusta tablice []. NIE twórz wpisu opisujacego brak wynikow, NIE wpisuj w pole tytul zdania w stylu "brak potwierdzonych aktow" - pusta tablica to jedyna poprawna odpowiedz w takim przypadku. Zwracasz WYLACZNIE dane zgodne ze schematem JSON.';

const userPrompt = 'Znajdz nowe lub zaktualizowane akty wykonawcze, delegowane, formalne wytyczne (guidelines) lub kody postepowania (codes of practice) FORMALNIE WYDANE lub zapowiedziane w ciagu ostatniego miesiaca w ramach AI Act. Pomin wszystko, co nie jest konkretnym, nazwanym instrumentem prawnym (patrz wykluczenia w instrukcji systemowej). Jesli nic takiego nie istnieje, zwroc pusta tablice akty: [] - to poprawna i oczekiwana odpowiedz, nie blad. Dla kazdego prawdziwego aktu podaj tytul, status, i opis wyjasniajacy prostym jezykiem, bez zargonu prawniczego ani technicznego, maksymalnie 2 zdania. Status przyjety_opublikowany tylko dla zrodel oficjalnych (eur-lex.europa.eu, digital-strategy.ec.europa.eu).';

const body = {
  model: 'sonar',
  max_tokens: 4096,
  messages: [
    { role: 'system', content: systemPrompt },
    { role: 'user', content: userPrompt }
  ],
  response_format: {
    type: 'json_schema',
    json_schema: {
      name: 'executive_acts_check',
      schema: {
        type: 'object',
        properties: {
          akty: {
            type: 'array',
            items: {
              type: 'object',
              properties: {
                tytul: { type: 'string' },
                status: { type: 'string', enum: ['zapowiedziany', 'w_konsultacjach', 'przyjety_opublikowany'] },
                opis_prostym_jezykiem: { type: 'string' },
                zrodlo_domena: { type: 'string' },
                data_zdarzenia: { type: ['string', 'null'] }
              },
              required: ['tytul', 'status', 'opis_prostym_jezykiem', 'zrodlo_domena']
            }
          }
        },
        required: ['akty']
      }
    }
  },
  search_domain_filter: ['eur-lex.europa.eu', 'digital-strategy.ec.europa.eu', 'artificialintelligenceact.eu', 'iapp.org', 'lexology.com'],
  search_recency_filter: 'month'
};

return [{ json: { requestBody: body } }];

const text = $json.choices[0].message.content;
const parsed = JSON.parse(text);
return [{ json: parsed }];

function normalizeKey(tytul) {
  return (tytul || '')
    .toLowerCase()
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9\s]/g, '')
    .split(/\s+/)
    .filter(w => w && !['the','on','w','sprawie','o','do','dla','i','oraz','of','and','for'].includes(w))
    .slice(0, 6)
    .join('_');
}

function pomin(item) {
  const tekst = ((item.tytul || '') + ' ' + (item.opis_prostym_jezykiem || '')).toLowerCase();
  const sygnalyPlaceholder = ['brak potwierdz', 'brak wynik', 'nie znaleziono', 'no confirmed', 'no new', 'no results', 'zadnych nowych'];
  const sygnalyAdministracyjne = ['privacy statement', 'oswiadczenie o prywatnosci', 'polityka prywatnosci', 'cookie', 'accessibility statement', 'terms of use', 'disclaimer', 'faq'];
  // jesli model sam zaprzecza kwalifikacji we wlasnym opisie - ufamy temu zaprzeczeniu bardziej niz polu status
  const samozaprzeczenie = ['nie jest to samodzielny akt', 'nie jest to akt wykonawczy', 'nie jest aktem wykonawczym', 'nie jest wytyczn'];
  const wszystkie = [...sygnalyPlaceholder, ...sygnalyAdministracyjne, ...samozaprzeczenie];
  return wszystkie.some(s => tekst.includes(s));
}

const previous = $('Parse State').first().json.data.akty_wykonawcze || [];
const nowe = ($json.akty || []).filter(a => !pomin(a));
const oficjalne = ['eur-lex.europa.eu', 'digital-strategy.ec.europa.eu'];
const statusRank = { zapowiedziany: 1, w_konsultacjach: 2, przyjety_opublikowany: 3 };

const mapa = {};
for (const p of previous) mapa[p.klucz] = { ...p, zmieniono_w_tym_uruchomieniu: false };

const dzis = new Date().toISOString().slice(0, 10);

for (const a of nowe) {
  const klucz = normalizeKey(a.tytul);
  const zrodloOficjalne = oficjalne.some(d => (a.zrodlo_domena || '').includes(d));
  const faktycznyStatus = (a.status === 'przyjety_opublikowany' && !zrodloOficjalne) ? 'w_konsultacjach' : a.status;

  if (!mapa[klucz]) {
    mapa[klucz] = {
      klucz: klucz,
      tytul: a.tytul,
      status: faktycznyStatus,
      opis_prostym_jezykiem: a.opis_prostym_jezykiem,
      zrodlo_domena: a.zrodlo_domena,
      data_zdarzenia: a.data_zdarzenia || null,
      pierwsza_wzmianka: dzis,
      zmieniono_w_tym_uruchomieniu: true
    };
  } else {
    const obecny = mapa[klucz];
    if ((statusRank[faktycznyStatus] || 0) > (statusRank[obecny.status] || 0)) {
      mapa[klucz] = {
        ...obecny,
        status: faktycznyStatus,
        opis_prostym_jezykiem: a.opis_prostym_jezykiem || obecny.opis_prostym_jezykiem,
        zrodlo_domena: a.zrodlo_domena,
        data_zdarzenia: a.data_zdarzenia || obecny.data_zdarzenia || null,
        zmieniono_w_tym_uruchomieniu: true
      };
    } else {
      mapa[klucz] = { ...obecny, zmieniono_w_tym_uruchomieniu: false };
    }
  }
}

return [{ json: { akty_wykonawcze: Object.values(mapa) } }];

const state = $input.first().json;
const items = state.data.implementacja_pl;
const listaTekst = items.map(m => '- id: ' + m.id + ' | ' + m.nazwa + ' | obecny znany status: ' + m.status + ' | obecna znana data: ' + m.data_aktualna).join('\n');

const systemPrompt = 'Jestes asystentem monitorujacym wdrozenie unijnego AI Act w Polsce (ustawa o systemach sztucznej inteligencji z 3 lipca 2026, Komisja Rozwoju i Bezpieczenstwa Sztucznej Inteligencji - KRiBSI). Dla nowych elementow spoza znanej listy stosujesz te same rygorystyczne kryteria co przy aktach wykonawczych: tylko formalnie wydane rozporzadzenia wykonawcze, oficjalne obwieszczenia ministerstwa lub UODO, lub inne konkretne, nazwane dzialania formalne. NIE zaliczaj: artykulow informacyjnych i wpisow blogowych, poradnikow, list kontrolnych i materialow pomocniczych, FAQ, naborow, konkursow i ogloszen o dofinansowanie, komunikatow o ustanowieniu programow badawczych lub wspierajacych, konsultacji spolecznych bez opublikowanego projektu aktu. Nowy element musi byc nazwanym aktem prawnym albo formalnym obwieszczeniem organu, z data lub numerem. Jesli nie znajdziesz zadnych nowych elementow spelniajacych kryteria, zwroc nowe_elementy jako pusta tablice [] - NIE twórz wpisu opisujacego brak wynikow. Zwracasz WYLACZNIE dane zgodne ze schematem JSON.';

const userPrompt = 'Sprawdz status ponizszych elementow implementacji ustawy o systemach AI w Polsce:\n\n' + listaTekst + '\n\nDodatkowo: czy pojawily sie nowe rozporzadzenia wykonawcze do tej ustawy, nowe formalne obwieszczenia Ministerstwa Cyfryzacji lub UODO, albo inne konkretne, formalne wydarzenia we wdrozeniu, ktore nie pasuja do powyzszej listy? Jesli tak, opisz je prostym jezykiem, bez zargonu prawniczego, maksymalnie 2 zdania. Jesli nic takiego nie ma, zwroc nowe_elementy: [] - to poprawna odpowiedz, nie blad.';

const body = {
  model: 'sonar',
  max_tokens: 4096,
  messages: [
    { role: 'system', content: systemPrompt },
    { role: 'user', content: userPrompt }
  ],
  response_format: {
    type: 'json_schema',
    json_schema: {
      name: 'pl_implementation_check',
      schema: {
        type: 'object',
        properties: {
          items: {
            type: 'array',
            items: {
              type: 'object',
              properties: {
                id: { type: 'string' },
                ocena: { type: 'string', enum: ['bez_zmian', 'zapowiedziana_zmiana', 'potwierdzona_zmiana'] },
                nowa_data: { type: ['string', 'null'] },
                zrodlo_domena: { type: 'string' },
                notatka: { type: 'string' }
              },
              required: ['id', 'ocena', 'zrodlo_domena', 'notatka']
            }
          },
          nowe_elementy: {
            type: 'array',
            items: {
              type: 'object',
              properties: {
                tytul: { type: 'string' },
                opis_prostym_jezykiem: { type: 'string' },
                status: { type: 'string', enum: ['zapowiedziany', 'w_konsultacjach', 'przyjety_opublikowany'] },
                zrodlo_domena: { type: 'string' }
              },
              required: ['tytul', 'opis_prostym_jezykiem', 'status', 'zrodlo_domena']
            }
          }
        },
        required: ['items', 'nowe_elementy']
      }
    }
  },
  search_domain_filter: ['gov.pl', 'uodo.gov.pl', 'sejm.gov.pl', 'eli.gov.pl', 'iapp.org', 'lexology.com'],
  search_recency_filter: 'month'
};

return [{ json: { requestBody: body } }];

const text = $json.choices[0].message.content;
const parsed = JSON.parse(text);
return [{ json: parsed }];

function wygladaJakPlaceholder(item) {
  const tekst = ((item.tytul || '') + ' ' + (item.opis_prostym_jezykiem || '') + ' ' + (item.status || '')).toLowerCase();
  const sygnaly = [
    'brak potwierdz', 'brak wynik', 'nie znaleziono', 'no confirmed', 'no new', 'no results', 'zadnych nowych',
    'nie jest to samodzielny akt', 'nie jest to akt wykonawczy', 'nie jest aktem wykonawczym', 'nie jest wytyczn',
    'informacja ogolna', 'bez nowego formalnego', 'brak nowego formalnego', 'nie jest formaln', 'general information', 'no new formal',
    'nie jest decyzj', 'nie stanowi formalnego', 'nie stanowi aktu'
  ];
  return sygnaly.some(s => tekst.includes(s));
}

function normalizeKey(tytul) {
  return (tytul || '')
    .toLowerCase()
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9\s]/g, '')
    .split(/\s+/)
    .filter(w => w && !['the','on','w','sprawie','o','do','dla','i','oraz','of','and','for'].includes(w))
    .slice(0, 6)
    .join('_');
}

const previous = $('Parse State').first().json.data.implementacja_pl || [];
const ocenyBy = {};
for (const o of $json.items) ocenyBy[o.id] = o;

const oficjalne = ['gov.pl', 'uodo.gov.pl', 'sejm.gov.pl', 'eli.gov.pl'];

const zaktualizowane = previous.map(item => {
  const ocena = ocenyBy[item.id];
  if (!ocena || ocena.ocena === 'bez_zmian') {
    return { ...item, zmieniono_w_tym_uruchomieniu: false };
  }
  const zrodloOficjalne = oficjalne.some(d => (ocena.zrodlo_domena || '').includes(d));
  if (ocena.ocena === 'potwierdzona_zmiana' && zrodloOficjalne) {
    return {
      ...item,
      status: 'zaktualizowany',
      data_aktualna: ocena.nowa_data || item.data_aktualna,
      ostatnia_zmiana: ocena.notatka,
      zmieniono_w_tym_uruchomieniu: true
    };
  }
  if (item.status !== 'zaktualizowany') {
    const nowosc = item.status !== 'zagrozony_zmiana' || item.ostatnia_zmiana !== ocena.notatka;
    return {
      ...item,
      status: 'zagrozony_zmiana',
      ostatnia_zmiana: ocena.notatka,
      zmieniono_w_tym_uruchomieniu: nowosc
    };
  }
  return { ...item, zmieniono_w_tym_uruchomieniu: false };
});

// Klucz liczymy z tytulu, a dla wpisow juz zapisanych bierzemy id ALBO
// odtwarzamy klucz z nazwy - inaczej wpis zapisany kiedys bez id nie blokuje
// ponownego dodania tego samego elementu. Set rosnie w trakcie petli, wiec
// lapie tez duplikaty w obrebie jednej odpowiedzi modelu.
// Nowe elementy NIE wchodza do sledzonego stanu. Powod: model potrafi zwrocic
// rzecz, ktora w swoim wlasnym opisie dyskwalifikuje, i potrafi opisac ten sam
// fakt innym tytulem niz pozycja juz sledzona - wtedy zaden klucz tego nie zlapie.
// Ida wiec do maila jako sygnaly do recznego sprawdzenia. Jesli ktorys okaze sie
// realny, dopisujemy go recznie jako stala pozycje z wlasnym opisem.
const kluczWpisu = (x) => x.id || ('pl_' + normalizeKey(x.nazwa || x.tytul));
const znaneKlucze = new Set(zaktualizowane.map(kluczWpisu));

const sygnaly = [];
for (const n of ($json.nowe_elementy || [])) {
  if (wygladaJakPlaceholder(n)) continue;
  const klucz = 'pl_' + normalizeKey(n.tytul);
  if (znaneKlucze.has(klucz)) continue;   // nie powtarzaj tego, co juz sledzimy
  znaneKlucze.add(klucz);                 // ani tego samego dwa razy w jednej odpowiedzi
  sygnaly.push({
    tytul: n.tytul,
    opis_prostym_jezykiem: n.opis_prostym_jezykiem,
    zrodlo_domena: n.zrodlo_domena
  });
}

return [{ json: { implementacja_pl: zaktualizowane, sygnaly: sygnaly } }];

const kamienie = $('Code - Merge Ratchet Kamienie').first().json.kamienie_milowe;
const akty = $('Code - Merge Ratchet Akty').first().json.akty_wykonawcze;
const plNode = $('Code - Merge Ratchet PL').first().json;
const pl = plNode.implementacja_pl;
const sygnaly = plNode.sygnaly || [];

const stan = {
  ostatnia_aktualizacja: new Date().toISOString(),
  kamienie_milowe: kamienie,
  akty_wykonawcze: akty,
  implementacja_pl: pl
};

// sygnaly celowo poza obiektem 'stan' - do maila tak, na dysk nie
return [{ json: { stan: stan, sygnaly: sygnaly } }];

const stanJson = JSON.stringify($json.stan, null, 2);
const binary = await this.helpers.prepareBinaryData(Buffer.from(stanJson, 'utf-8'), 'ai_act_monitor_state.json', 'application/json');
return [{ json: { stan: $json.stan }, binary: { data: binary } }];

const wejscie = $('Code - Combine All Sections').first().json;
const stan = wejscie.stan;
const sygnaly = wejscie.sygnaly || [];

function ikona(status) {
  const map = {
    obowiazuje: '\u2705',
    wchodzi_w_zycie: '\ud83d\udfe1',
    nadchodzi: '\u23f3',
    zagrozony_zmiana: '\u26a0\ufe0f',
    przesuniete: '\ud83d\udd04',
    oczekiwane: '\u23f3',
    zaktualizowany: '\ud83d\udd04',
    zapowiedziany: '\ud83c\udd95',
    w_konsultacjach: '\ud83d\udcdd',
    przyjety_opublikowany: '\u2705'
  };
  return map[status] || '\u2022';
}

function formatujDate(d) {
  return d ? d : 'brak daty';
}

// tytuly i opisy pochodza od modelu - bez escapowania jeden znak < psuje cala tabele
function esc(s) {
  return String(s == null ? '' : s)
    .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}

const zmiany = [];
for (const item of stan.kamienie_milowe) {
  if (item.zmieniono_w_tym_uruchomieniu) zmiany.push('<li><strong>' + esc(item.nazwa) + ':</strong> ' + esc(item.ostatnia_zmiana) + '</li>');
}
for (const item of stan.akty_wykonawcze) {
  if (item.zmieniono_w_tym_uruchomieniu) zmiany.push('<li><strong>' + esc(item.tytul) + ':</strong> ' + esc(item.opis_prostym_jezykiem) + '</li>');
}
for (const item of stan.implementacja_pl) {
  if (item.zmieniono_w_tym_uruchomieniu) zmiany.push('<li><strong>' + esc(item.nazwa) + ':</strong> ' + esc(item.ostatnia_zmiana) + '</li>');
}

const sekcjaZmiany = zmiany.length
  ? '<h2>Co sie zmienilo od ostatniego tygodnia</h2><ul>' + zmiany.join('') + '</ul>'
  : '<h2>Co sie zmienilo od ostatniego tygodnia</h2><p>Nic sie nie zmienilo - wszystko zgodnie z poprzednim stanem.</p>';

const wierszKamien = i => '<tr><td>' + ikona(i.status) + '</td><td><strong>' + esc(i.nazwa) + '</strong><br><span style="color:#555;font-size:14px;">' + esc(i.opis_prostym_jezykiem) + '</span></td><td>' + esc(formatujDate(i.data_aktualna)) + '</td></tr>';

const sekcjaKamienie = '<h2>Harmonogram AI Act</h2><table style="width:100%;border-collapse:collapse;">' + stan.kamienie_milowe.map(wierszKamien).join('') + '</table>';

const sekcjaPL = '<h2>Wdrozenie w Polsce</h2><table style="width:100%;border-collapse:collapse;">' + stan.implementacja_pl.map(wierszKamien).join('') + '</table>';

const sekcjaAkty = stan.akty_wykonawcze.length
  ? '<h2>Akty wykonawcze i wytyczne</h2><table style="width:100%;border-collapse:collapse;">' + stan.akty_wykonawcze.map(a => '<tr><td>' + ikona(a.status) + '</td><td><strong>' + esc(a.tytul) + '</strong>' + (a.data_zdarzenia ? ' <span style="color:#999;font-size:13px;">(' + esc(a.data_zdarzenia) + ')</span>' : '') + '<br><span style="color:#555;font-size:14px;">' + esc(a.opis_prostym_jezykiem) + '</span></td></tr>').join('') + '</table>'
  : '<h2>Akty wykonawcze i wytyczne</h2><p>Brak nowych aktow w tym tygodniu.</p>';

const sekcjaSygnaly = sygnaly.length
  ? '<h2>Sygnaly do sprawdzenia</h2>' +
    '<p style="color:#777;font-size:14px;">Znalezione w tym tygodniu, ale niezweryfikowane. To nie sa sledzone pozycje - jesli ktoras okaze sie istotna, dopisz ja recznie do pliku stanu.</p>' +
    '<ul>' + sygnaly.map(s => '<li><strong>' + esc(s.tytul) + '</strong> <span style="color:#999;font-size:13px;">' + esc(s.zrodlo_domena) + '</span><br><span style="color:#555;font-size:14px;">' + esc(s.opis_prostym_jezykiem) + '</span></li>').join('') + '</ul>'
  : '';

const html = '<div style="font-family:Arial,sans-serif;max-width:640px;margin:0 auto;">' +
  '<h1>Cotygodniowy przeglad: AI Act i wdrozenie w Polsce</h1>' +
  '<p style="color:#777;">' + new Date().toLocaleDateString('pl-PL') + '</p>' +
  sekcjaZmiany + sekcjaKamienie + sekcjaPL + sekcjaAkty + sekcjaSygnaly +
  '<hr><p style="color:#999;font-size:12px;">Kolejne sprawdzenie: za tydzien, w sobote o 9:00. Zrodla: EUR-Lex, Komisja Europejska/AI Office, Sejm, gov.pl, UODO oraz wybrane serwisy branzowe.</p>' +
  '</div>';

return [{ json: { subject: 'Cotygodniowy przeglad: AI Act i wdrozenie w Polsce', html: html } }];
